  <script>
    const notificationOptions = [
      { id: "notify-email", value: "Email", label: "Email" },
      { id: "notify-sms", value: "SMS", label: "SMS" },
      { id: "notify-push", value: "Push Notifications", label: "Push Notifications" }
    ];

    const RadioOption = ({ id, value, label }) => `
      <label class="radio-option" for="${id}">
        <input type="radio" id="${id}" name="notification-preference" value="${value}" required />
        <span>${label}</span>
      </label>
    `;

    const NotificationForm = () => `
      <p class="eyebrow">Preferences</p>
      <h1>Notification delivery</h1>
      <p class="intro">Choose one way you would like to receive updates.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-indicator" aria-hidden="true">*</span>
              <span class="sr-only">Required</span>
            </legend>
            <p class="help-text" id="notification-help">Select a single option from the list below.</p>
            <div class="radio-list" role="presentation">
              ${notificationOptions.map(RadioOption).join("")}
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </div>
      </form>
    `;

    document.getElementById("app").innerHTML = NotificationForm();

    const form = document.getElementById("notification-form");
    const status = document.getElementById("form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.reportValidity()) {
        status.textContent = "";
        return;
      }

      const selected = new FormData(form).get("notification-preference");
      status.textContent = `Preference saved: ${selected}.`;
    });
  </script>
</body>
